"""Which failures are allowed to vote, and which are the suite confessing (T2.5, T2.6, D25).

`_run` turns a `ProbeError` out of a check into a failed assertion, and gives a reason for it:
a subject that cannot be resolved *after* the call is a statement about the call — `new:people`
with nothing new is precisely the failure a use case is looking for.

That reason covers exactly one of the three `ProbeError`s a subject lookup can raise. The other
two say nothing about the call:

* `subject 'x' is not declared by this use case` — a typo in a YAML file.
* `subject 'x' names 7 objects where one is meant` — a kind reading a set as one object.

Both are the suite being wrong about its own data, and both went out over the finding channel.
The second one did it for real: uc21 failed 3 of 3 runs of the first full sweep and the sweep
wrote an issue draft accusing the product, against a public repository, for a defect that was
entirely in `tests/e2e`. A wrong grader must not be reported as a wrong product — that rule
already existed for `GradingError`; these two simply were not routed through it.

The over-correction is the interesting half: silencing "the call produced nothing" would
silence the finding uc2, uc6 and uc16 exist to make. So it is pinned here from both sides.
"""

from __future__ import annotations

from typing import Any

import pytest
from fixtures import stage2_records as make
from stage2 import grading
from stage2.catalog import Assertion, UseCase

BEFORE = make.state(
    people=(
        make.person("I0000", "Bertram", "Aschenblum", gender=make.MALE),
        make.person("I0001", "Cordula", "Aschenblum"),
        make.person("I0002", "Rosalind", "Steinbrecht"),
    ),
)


def use_case(*assertions: Assertion) -> UseCase:
    return UseCase(
        id="uc0",
        slug="uc00-probe",
        tier=1,
        prompt="p",
        primary=("gramps_add_person",),
        decoys=(),
        secondary=(),
        subjects={
            "the_lot": {"namespace": "people", "surname": "Aschenblum", "count": 2},
            "target": {"namespace": "people", "first_name": "Rosalind", "surname": "Steinbrecht"},
        },
        guards={"people": [], "families": [], "sources": []},
        maxdrop=0,
        assertions=assertions,
        waivers=(),
        path=make.__file__,  # type: ignore[arg-type]
    )


def grade(assertion: Assertion, after: Any = BEFORE) -> list[grading.Outcome]:
    case = use_case(assertion)
    return grading.grade(case, grading.evidence_for(case, BEFORE, after))


def test_a_subject_the_use_case_never_declared_is_a_harness_fault() -> None:
    """A typo in a YAML file cannot be evidence about a genealogy server."""
    with pytest.raises(grading.GradingError, match="harness bug"):
        grade(Assertion("a", "person", {"subject": "the_lto", "fields": {"gender": 0}}))


def test_a_set_handed_to_a_kind_that_grades_one_is_a_harness_fault() -> None:
    """uc21's actual failure, as the sweep would classify it now.

    The lint refuses this catalog before a run is paid for; this is the second net, for the
    pairing the lint cannot see — and the one that decides whether the draft accuses the
    product or the suite.
    """
    with pytest.raises(grading.GradingError, match="harness bug"):
        grade(Assertion("a", "alternates", {"subject": "the_lot", "count": 1}))


def test_nothing_arriving_is_still_a_finding() -> None:
    """The over-correction guard.

    `new:people` resolving to nothing is the whole point of a create use case: the model was
    asked to add somebody and did not. Routing it to `GradingError` would abort the sweep on
    the very failure it is there to catch, and every create use case would go quiet at once.
    """
    outcomes = grade(
        Assertion("a", "person", {"subject": "new:people", "fields": {"surname": "Sorge"}})
    )

    assert not outcomes[0].passed
    assert "appeared" in outcomes[0].detail


def test_a_failing_assertion_is_still_a_finding() -> None:
    """The other side of the same guard: a wrong value is a product statement, not a fault."""
    outcomes = grade(Assertion("a", "person", {"subject": "target", "fields": {"surname": "Nope"}}))

    assert not outcomes[0].passed
    assert "Steinbrecht" in outcomes[0].detail
